public static String keyByWord(String word) {
    char[] sortedWord = word.toCharArray();
    Map<Character, Integer> symCnt = new HashMap();
    for (char sym : sortedWord) {
        if (!symCnt.containsKey(sym)) {
            symCnt.put(sym, 0);
        }
        symCnt.put(sym, symCnt.get(sym) + 1);
